export async function showPrevention({api,root,esc,stillCurrent,operator,authRequired,onUnlocked}){
 if(!operator){root.innerHTML=authRequired?'<section><h2>Merchant access required</h2><p>An Admin or Manager can inspect prevention patterns and rehearse a connector change.</p><a class="button" href="account.html">Open merchant account</a></section>':'<section><span class="eyebrow">PREVENTION STUDIO</span><h2>Unlock the merchant view</h2><p>Prevention patterns and connector rehearsals stay inside the merchant workspace.</p><form id="prevention-unlock" class="filters"><label>Operator key<input type="password" name="key" autocomplete="off" required></label><button class="primary">Unlock Prevention Studio</button></form></section>';const form=root.querySelector('#prevention-unlock');if(form)form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('operator',{key:new FormData(form).get('key')});await onUnlocked();}catch(error){root.querySelector('p').textContent=error.message||'Merchant access could not be unlocked.';button.disabled=false;}};return;}
 const data=await api('prevention');if(!stillCurrent())return;
 const provider=data.patterns.filter(p=>p.source==='paypal-sandbox'),sample=data.patterns.filter(p=>p.source==='sample');
 const card=p=>`<article class="prevention-pattern"><div class="prevention-pattern-top"><span class="pill ${p.source==='paypal-sandbox'?'good':''}">${p.source==='paypal-sandbox'?'PayPal sandbox evidence':'Illustrative sample'}</span><span class="prevention-count">${p.count} related purchases</span></div><h3>${esc(p.symptom)}</h3><p>${esc(p.courseId)} · ${p.verified} previously verified · ${p.open} still open</p><div class="prevention-evidence"><strong>Supporting cases</strong><div>${p.caseIds.map(id=>`<code>${esc(id)}</code>`).join('')}</div></div><div class="prevention-hypothesis"><span>Working hypothesis</span><p>${esc(p.hypothesis)}</p></div><p class="prevention-next"><b>Safe next step:</b> ${esc(p.next)}</p></article>`;
 root.innerHTML=`<section class="prevention-hero"><span class="eyebrow">PREVENTION STUDIO</span><h2>Fix the pattern behind the repair.</h2><p>PayTrace groups recurring paid-access failures after a recovery. A shared symptom is a lead for investigation, never proof that the connector caused it.</p><div class="prevention-flow"><div><b>01</b><strong>Recover</strong><span>Verify the buyer’s lesson.</span></div><div><b>02</b><strong>Recognize</strong><span>Compare saved outcomes.</span></div><div><b>03</b><strong>Prevent</strong><span>Rehearse a mapping change before activation.</span></div></div></section>
 <section><div class="actions"><div><span class="eyebrow">PAST ${data.windowDays} DAYS</span><h2>Recurring signals</h2></div><a class="button" href="connection-studio.html#replay">Rehearse a connector mapping →</a></div><p class="notice">${esc(data.definition)} No connector setting or customer access is changed on this screen.</p>${provider.length?`<div class="prevention-grid">${provider.map(card).join('')}</div>`:'<p>No recurring PayPal sandbox recovery pattern is recorded yet. Complete connected purchases and verification before claiming a live prevention signal.</p>'}</section>
 ${sample.length?`<section><h2>Illustrative patterns</h2><p>These fictional cases show how Prevention Studio would present a recurring signal. They are separate from PayPal sandbox evidence.</p><div class="prevention-grid">${sample.map(card).join('')}</div></section>`:'<section><span class="eyebrow">FICTIONAL WALKTHROUGH</span><h2>What a prevention signal would look like</h2><p>Imagine three workshop buyers paid successfully, two later received verified access, and all three had the same enrollment timeout. PayTrace would group those cases, flag the timeout as a shared symptom, and suggest checking the store-to-course handoff. The merchant would rehearse a mapping correction before saving it; only a fresh matching PayPal sandbox capture could activate the new mapping.</p><p class="notice">This example is a story illustration, not a pattern found in this workspace or proof that a mapping change fixes the cause.</p></section>'}
 <section class="prevention-guardrail"><span class="eyebrow">MERCHANT CONTROL</span><h2>From hypothesis to safer change</h2><p>Connection Studio can compare up to ten store event samples under the current and proposed field mappings. The rehearsal reads only those samples and returns field categories, never buyer values. Saving a draft deactivates the current mapping; activating it requires a fresh matching PayPal sandbox capture. New purchases are then checked individually.</p><a class="button" href="connection-studio.html#replay">Open mapping rehearsal</a></section>`;
}
